import { pickRandomSampleQueries } from "@/lib/sample-queries";
import { config } from "@/lib/config";

export const dynamic = "force-dynamic";

export default async function HomePage() {
  let initialSamples: { id: string; text: string }[] = [];
  let samplesError: string | null = null;

  try {
    initialSamples = await pickRandomSampleQueries(config.sampleQueriesCount);
  } catch (err) {
    samplesError =
      err instanceof Error ? err.message : "Could not load sample queries.";
  }

  return (
    <main className="container">
      <header className="hero">
        <h1>MS MARCO Passage Search</h1>
        <p>
          Search the MS MARCO passage corpus via the Anserini REST API. Sample queries
          are drawn at random from the MS MARCO passage dev set on every page load.
        </p>
      </header>

      <SearchClient initialSamples={initialSamples} samplesError={samplesError} />

      <footer className="notes">
        Backend: <code>{config.anseriniBaseUrl}</code>{" "}
        · Index: <code>{config.anseriniIndex}</code>
      </footer>
    </main>
  );
}

"use client";

import { FormEvent, useCallback, useEffect, useRef, useState } from "react";

type SampleQuery = { id: string; text: string };

type ResultRow = {
  rank: number;
  docid: string;
  score: number;
  text: string;
};

type SearchResponse = {
  index: string;
  query: string;
  results: ResultRow[];
};

type Status =
  | { kind: "idle" }
  | { kind: "loading"; query: string }
  | { kind: "error"; message: string }
  | { kind: "ready"; data: SearchResponse };

export default function SearchClient({
  initialSamples,
  samplesError,
}: {
  initialSamples: SampleQuery[];
  samplesError: string | null;
}) {
  const [query, setQuery] = useState("");
  const [samples, setSamples] = useState<SampleQuery[]>(initialSamples);
  const [sampleErr, setSampleErr] = useState<string | null>(samplesError);
  const [status, setStatus] = useState<Status>({ kind: "idle" });
  const inputRef = useRef<HTMLInputElement>(null);
  const reqIdRef = useRef(0);

  // If server-side sample loading failed (or returned nothing) try refetching
  // from the API once the client mounts — this makes the page recover from
  // transient FS / startup issues without a full reload.
  useEffect(() => {
    if (initialSamples.length > 0) return;
    let cancelled = false;
    (async () => {
      try {
        const res = await fetch("/api/sample-queries", { cache: "no-store" });
        const body = await res.json();
        if (cancelled) return;
        if (res.ok && Array.isArray(body.samples)) {
          setSamples(body.samples);
          setSampleErr(null);
        } else if (body?.error) {
          setSampleErr(String(body.error));
        }
      } catch (err) {
        if (!cancelled) {
          setSampleErr(err instanceof Error ? err.message : String(err));
        }
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [initialSamples.length]);

