import path from "node:path";

// Server-side configuration. Everything is overridable via env vars; we never
// pause the app to ask for ports — defaults match the PRD.
export const config = {
  anseriniBaseUrl: (process.env.ANSERINI_BASE_URL ?? "http://localhost:8080").replace(/\/$/, ""),
  anseriniIndex: process.env.ANSERINI_INDEX ?? "msmarco-v1-passage",
  sampleQueriesPath:
    process.env.SAMPLE_QUERIES_PATH ??
    path.join(process.cwd(), "data", "msmarco-passage-dev-queries.json"),
  sampleQueriesCount: Number.parseInt(process.env.SAMPLE_QUERIES_COUNT ?? "6", 10) || 6,
  defaultHits: Number.parseInt(process.env.SEARCH_HITS ?? "10", 10) || 10,
};

import { promises as fs } from "node:fs";
import { config } from "./config";

export type SampleQuery = { id: string; text: string };

let cache: SampleQuery[] | null = null;

async function loadAll(): Promise<SampleQuery[]> {
  if (cache) return cache;
  const raw = await fs.readFile(config.sampleQueriesPath, "utf8");
  const parsed = JSON.parse(raw) as SampleQuery[];
  cache = parsed.filter((q) => q && typeof q.text === "string" && q.text.trim().length > 0);
  return cache;
}

export async function pickRandomSampleQueries(count: number): Promise<SampleQuery[]> {
  const all = await loadAll();
  if (all.length === 0) return [];
  const n = Math.min(count, all.length);
  // Reservoir/Fisher-Yates partial shuffle over a copy of indices.
  const idx = Array.from({ length: all.length }, (_, i) => i);
  for (let i = 0; i < n; i++) {
    const j = i + Math.floor(Math.random() * (all.length - i));
    [idx[i], idx[j]] = [idx[j], idx[i]];
  }
  return idx.slice(0, n).map((i) => all[i]);
}

import { config } from "./config";

// Response shape per Anserini RestServer v1 (see anserini-cli skill):
//   { api, index, query: { text }, candidates: [{ docid, score, rank, doc }] }
export type AnseriniCandidate = {
  docid: string;
  score: number;
  rank: number;
  doc: string;
};

export type AnseriniSearchResponse = {
  api: string;
  index: string;
  query: { text: string };
  candidates: AnseriniCandidate[];
};

export class AnseriniError extends Error {
  status: number;
  constructor(message: string, status = 502) {
    super(message);
    this.status = status;
  }
}

export async function searchAnserini(query: string, hits: number): Promise<AnseriniSearchResponse> {
  const url =
    `${config.anseriniBaseUrl}/v1/${encodeURIComponent(config.anseriniIndex)}/search` +
    `?query=${encodeURIComponent(query)}&hits=${encodeURIComponent(String(hits))}`;

  let res: Response;
  try {
    res = await fetch(url, { cache: "no-store" });
  } catch (err) {
    throw new AnseriniError(
      `Could not reach Anserini REST server at ${config.anseriniBaseUrl}: ${
        err instanceof Error ? err.message : String(err)
      }`,
      503,
    );
  }

  if (!res.ok) {
    const body = await res.text().catch(() => "");
    throw new AnseriniError(
      `Anserini REST server returned ${res.status} ${res.statusText}${body ? `: ${body.slice(0, 200)}` : ""}`,
      502,
    );
  }

  const json = (await res.json()) as AnseriniSearchResponse;
  if (!json || !Array.isArray(json.candidates)) {
    throw new AnseriniError("Anserini REST response was not in the expected shape.", 502);
  }
  return json;
}

import { NextResponse } from "next/server";
import { config } from "@/lib/config";
import { pickRandomSampleQueries } from "@/lib/sample-queries";

export const dynamic = "force-dynamic";

export async function GET(request: Request) {
  const url = new URL(request.url);
  const countParam = url.searchParams.get("count");
  const count =
    countParam && Number.isFinite(Number(countParam)) && Number(countParam) > 0
      ? Math.min(50, Math.floor(Number(countParam)))
      : config.sampleQueriesCount;

  try {
    const samples = await pickRandomSampleQueries(count);
    return NextResponse.json(
      { samples },
      { headers: { "Cache-Control": "no-store" } },
    );
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    return NextResponse.json(
      {
        error: `Failed to load sample queries: ${message}`,
        hint:
          "Generate the dev-queries file with frontend/scripts/fetch-dev-queries.sh, " +
          "or set SAMPLE_QUERIES_PATH to a JSON array of {id, text} objects.",
      },
      { status: 500 },
    );
  }
}

import { NextResponse } from "next/server";
import { config } from "@/lib/config";
import { AnseriniError, searchAnserini } from "@/lib/anserini";

export const dynamic = "force-dynamic";

export async function GET(request: Request) {
  const url = new URL(request.url);
  const query = (url.searchParams.get("q") ?? "").trim();
  const hitsParam = url.searchParams.get("hits");
  const hits =
    hitsParam && Number.isFinite(Number(hitsParam)) && Number(hitsParam) > 0
      ? Math.min(100, Math.floor(Number(hitsParam)))
      : config.defaultHits;

  if (!query) {
    return NextResponse.json(
      { error: "Query must not be empty." },
      { status: 400 },
    );
  }

  try {
    const data = await searchAnserini(query, hits);
    return NextResponse.json(
      {
        index: data.index,
        query: data.query.text,
        results: data.candidates.map((c) => ({
          rank: c.rank,
          docid: c.docid,
          score: c.score,
          text: c.doc,
        })),
      },
      { headers: { "Cache-Control": "no-store" } },
    );
  } catch (err) {
    if (err instanceof AnseriniError) {
      return NextResponse.json({ error: err.message }, { status: err.status });
    }
    const message = err instanceof Error ? err.message : String(err);
    return NextResponse.json({ error: `Unexpected error: ${message}` }, { status: 500 });
  }
}

